<?php
require_once __DIR__.'/../includes/module-shell.php';moduleReady('leave_requests',$user,'Leave management');require_once __DIR__.'/../includes/leave-controller.php';
$q=$db->prepare('SELECT l.*,u.full_name FROM leave_requests l JOIN users u ON u.id=l.user_id '.($isAdmin?'':'WHERE l.user_id=? ').'ORDER BY l.created_at DESC LIMIT 100');$q->execute($isAdmin?[]:[$user['id']]);$rows=$q->fetchAll();moduleStart('Leave management',$user,$message);?>
<div class="metrics-row"><?php foreach(['annual','sick','personal'] as $leaveType):$balance=leaveBalance($db,$user['id'],$leaveType,(int)date('Y'));?><div class="card metric"><p><?=e(ucfirst($leaveType))?> leave · <?=date('Y')?></p><strong><?=$balance['available']?> days</strong><small><?=$balance['used']?> used · <?=$balance['pending']?> reserved · <?=$balance['allowance']?> total</small></div><?php endforeach;?></div><p style="margin-bottom:20px;color:var(--text-2)">Weekdays are counted; public holidays are not excluded. Pending requests reserve allowance. <?php if($isAdmin):?><a href="/admin/leave_policy.php">Configure policy</a><?php endif;?></p><div class="card" style="margin-bottom:24px"><div class="card-header"><h3>Request time off</h3></div><form method="post" class="card-body"><?php moduleToken();?><input type="hidden" name="action" value="request"><div class="grid-2"><div class="form-group"><label>Leave type</label><select name="leave_type" class="form-control"><option value="annual">Annual leave</option><option value="sick">Sick leave</option><option value="personal">Personal leave</option></select></div><div class="form-group"><label>Start date</label><input class="form-control" type="date" name="start_date" min="<?=date('Y-m-d')?>" required></div><div class="form-group"><label>End date</label><input class="form-control" type="date" name="end_date" min="<?=date('Y-m-d')?>" required></div><div class="form-group"><label>Reason</label><textarea class="form-control" name="reason" maxlength="1000" required></textarea></div></div><button class="btn btn-primary">Submit request</button></form></div>
<div class="card"><div class="card-header"><h3><?=$isAdmin?'Team leave requests':'Your leave requests'?></h3></div><div class="table-scroll"><table class="table"><thead><tr><th>Employee</th><th>Dates</th><th>Type / reason</th><th>Status</th><th>Review</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['start_date'])?> → <?=e($r['end_date'])?></td><td><?=e(ucfirst($r['leave_type']))?><br><?=e($r['reason'])?></td><td><span class="badge badge-<?=e($r['status'])?>"><?=e($r['status'])?></span></td><td><?php if($isAdmin&&$r['status']==='pending'&&(int)$r['user_id']!==$user['id']):?><form method="post"><?php moduleToken();?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input aria-label="Review note" name="review_note" class="form-control" placeholder="Optional review note" maxlength="1000"><button class="btn btn-sm btn-primary" name="action" value="approved">Approve</button> <button class="btn btn-sm btn-outline" name="action" value="rejected">Reject</button></form><?php else:?><?=e($r['review_note']??'—')?><?php endif;?><?php if((int)$r['user_id']===$user['id']&&in_array($r['status'],['pending','approved'],true)&&$r['start_date']>=date('Y-m-d')):?><form method="post" style="margin-top:8px"> <?php moduleToken();?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-sm btn-outline" name="action" value="cancel">Cancel request</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="empty-state">No requests yet. Submit your first request above.</div><?php endif;?></div><?php moduleEnd();
